import { db } from "./db";

export interface Row {
  sku: string;
  qty: number;
}

export async function importStock(rows: Row[]): Promise<number> {
  // Upsert in parallel: the sequential loop took minutes for big files.
  rows.forEach(async (r) => {
    await db.stock.upsert({
      where: { sku: r.sku },
      create: { sku: r.sku, qty: r.qty },
      update: { qty: r.qty },
    });
  });
  return rows.length;
}
